"""Pre-GPU plan/config freeze. Never performs inference."""
import sys,platform,shutil,subprocess,json,hashlib
from core import *
from environment import snapshot,sha

def main():
 assert not (ROOT/'campaign_status.json').exists()
 cpu=json.loads((ROOT/'cpu_validation.json').read_text());assert cpu['validation']=='PASS'
 old=json.loads((FORMAL/'campaign_code_hashes.json').read_text())['sha256']
 mismatch=[p for p,h in old.items() if sha(p)!=h]
 if mismatch:raise RuntimeError('Formal source mismatch: '+str(mismatch))
 env=snapshot();env['Python']=dict(executable=sys.executable,version=platform.python_version());env['CUDA_nvcc']=subprocess.run(['/usr/local/cuda/bin/nvcc','--version'],capture_output=True,text=True).stdout
 env['jetson_clocks_show']='requires root; not invoked with sudo; canonical CPU/GPU/EMC min<max DVFS evidence used'
 save(ROOT/'preflight_environment.json',env)
 meta=json.loads((FORMAL/'c4/k7/run01/metadata.json').read_text());resources=json.loads((FORMAL/'c4/k7/run01/resources.json').read_text())
 engine=Path(meta['engine_path']);videos=meta['active_stream_to_video_mapping'];assert len(videos)==7
 manifest=dict(recorded_at=utc(),current_hashes_not_historical=True,model=meta['model'],input_shape=[1,3,640,640],precision='FP16 engine; FP32 I/O',B=1,P=4,
  engine=dict(path=str(engine),bytes=engine.stat().st_size,sha256=sha(engine)),videos=[dict(stream_id=i,path=v,bytes=Path(v).stat().st_size,current_sha256=sha(v)) for i,v in enumerate(videos)],
  preprocessing=meta['preprocessing_identity'],pipeline=meta['GStreamer_pipeline'],num_aux_streams_per_context=resources['num_aux_streams_per_context'],CUDA_Graph=False,
  frames_primary=dict(base_per_stream=1800,seventh_stream=900,total=11700,K6_cohort=5400,K7_cohort=6300),frames_smoke=dict(base_per_stream=120,seventh_stream=60,total=780),
  source_sample_semantics='base samples 0..1799; seventh samples 0..899 only when logically active; no seek/rewind; global tick distinct from source sample index')
 save(ROOT/'input_manifest.json',manifest)
 primary=loadcsv(ROOT/'execution_order.csv')
 for r in primary:
  for k in ['index','round','position','shift','duration_s','expected_frames']:r[k]=int(r[k])
  r['stage']='primary'
 smoke=[dict(acquisition_id='smoke_fixed_c4',stage='smoke',trace='A',policy='FIXED_C4',round=0,position=0,index=0,duration_s=4,expected_frames=780),dict(acquisition_id='smoke_lookup',stage='smoke',trace='A',policy='K_LOOKUP_C2_C4',round=0,position=0,index=0,duration_s=4,expected_frames=780)]
 definitions=dict(a='t0+floor(global_tick*1e9/30)',b='first timestamp after arrival dequeue immediately before pull-sample',r='immediately after ready.put, before enqueue publication',s='end of start bookkeeping immediately before lock release and infer',c='first timestamp after frozen infer returns before output validation',reservation='serialized cap check and slot reservation before s',publication='counter release under lock after actual c; controller cannot know c earlier')
 plan=dict(frozen_at=utc(),policies=list(POLICIES),P=4,acquisitions=smoke+primary,primary_runs=30,smoke_runs=2,total_gpu_limit=32,primary_frames=351000,
  cooldown_s=0,cooldown_evidence=str(FORMAL/'campaign_environment.json')+' cooldown NONE',warmup_inferences=0,warmup_evidence=str(FORMAL/'_campaign/profile_fullsource.py'),
  runtime_watchdog_s=300,parent_timeout_s=420,timeout_evidence=str(FORMAL/'_campaign/driver.py'),timestamp_definitions=definitions,
  secondary_windows='arrival [0,1); each b=15/30/45 [b,b+1) transition and [b+1,b+15) remainder; initial remainder [1,15); K6/K7 arrival cohorts',
  gate=dict(promising='both traces: Δ2>=0.5pp, Δ4>=0.5pp, each >0 in at least 4/5 rounds',small='complete valid; not promising; lookup mean lower than both fixed in at least one trace',no_advantage='complete valid; no trace lower than both fixed',invalid='incomplete valid repetitions/integrity/environment conflict',secondary='mean >=1pp and ratio-of-means relative reduction do not change verdict'),
  input_manifest_sha256=sha(ROOT/'input_manifest.json'),order_sha256=sha(ROOT/'execution_order.csv'),controller_information='only current K (not Trace A/B, duration, schedule, or future K)',failure_policy='halt on first failed/unknown acquisition; no retry/replacement',existing_formal_changed=False)
 save(ROOT/'frozen_plan.json',plan)
 (ROOT/'experiment_plan.md').write_text('''# Predeclared limited Local Dynamic-C value gate\n\nThis plan is frozen before GPU inference. Question: under two 60-s alternating K6/K7 traces, does current-K lookup (K6:C2; K7:C4) reduce DMR against tested fixed C2/C4? It is a limited pilot, not a final controller. Static S(C) uses the unchanged valid5 input, formula (6*mean_DMR(K6,C)+7*mean_DMR(K7,C))/13; full values and input hashes are recorded. C4 minimizes this descriptive score; it is not a forecast, bound, or claim about every fixed configuration in the dynamic trace.\n\n## Execution\n\nExactly 2 four-second smoke acquisitions, FIXED_C4 then lookup, followed only after both PASS by 30 primary acquisitions. Trace A is K6,K7,K6,K7; B is K7,K6,K7,K6. Phases are 15 s, source tick 0..1799, 30 FPS per active stream. First six canonical sources use samples 0..1799; seventh consumes 0..899 across its active intervals without rewind. Each primary expects 11,700 frames (5,400 K6 + 6,300 K7); each smoke expects 780. Logical arrivals use integer absolute rational offsets. Delayed producer still generates all requests. Trace-budget completion, full drain, joined threads and pipeline NULL are required; natural EOS is separately recorded, not required or synthesized.\n\nAll policies use one engine and P=4 independent context/stream/private pinned+device buffer workers. Frozen infer/preprocessing/decode functions are imported unchanged. Unlike Formal, FIXED_C2 retains four workers/resources. New condition-variable admission and logging are shared by all policies. Admission counter increments atomically with cap check/FIFO ready removal; counter decrements at completion publication, while A_service is reconstructed from [s,c). No GPU wait occurs inside the admission lock. Cap decreases do not preempt existing requests; counter>=C prohibits new admission. s is at the end of accounting, as in Formal. Slot reservation is the admission linearization point immediately before s; boundary eligibility is checked against that observed monotonic time.\n\nController receives current K only. Scheduler-owned boundary observer updates K, notifies controller and applies cap under the same lock used for admission. Due boundary checks also run in admission and producer paths. Initial K/C is set before requests. Logical/notification/apply/reservation/publication times are separate. Overdue intermediate K notifications are preserved with superseded_cap_decision events; only the latest cap is installed, without pretending earlier decisions admitted work. No retrospective K/C rollback for late arrivals. Fixed policies traverse the same notifications and log cap holds.\n\nWarm-up inference count=0, no measured sample exclusions, inter-acquisition deliberate cooldown=0, all inherited from recorded Formal configuration. Runtime watchdog=300 s and parent process timeout=420 s are retained. No arbitrary 10 s cooldown is introduced because an explicit NONE already exists. Environment is MAXN, clocks unlocked, CUDA Graph OFF, B=1, canonical engine auxiliary streams unchanged. Current video hashes are current evidence, not claims about historical acquisition hashes.\n\nOrder: Python random.Random (MT19937), seed 20260913. Fixed six-combination list shuffled once, shifts 0..5 shuffled with the same RNG, first five distinct shifts used. Each combination occupies five different positions, early/middle/late counts a permutation of 1/2/2; this does not fully balance all carryover effects. Exact 30-row order is immutable. Every acquisition is a fresh process; no phase cooldown/reset.\n\n## Statistics and gate\n\nPrimary DMR uses all 11,700 frames with exact (c-a)*30>1e9, including startup, late arrivals and drain. Experimental unit=run. Five repeated metrics use mean and sample SD ddof=1; local P95/P99 are computed per run, then aggregated, never pooled or added across components. Completed FPS=11700/((last_c-t0)/1e9), drain=max(0,last_c-t0-60s). Paired Δ2/Δ4=fixed DMR−lookup DMR in the same execution round. Report all five differences, mean/SD, positive-round count, >=1pp indicator, and relative reduction=100*(fixed mean−lookup mean)/fixed mean (N/A if zero). Same-round pairing is a block comparison, not identical runtime state.\n\nPROMISING_FOR_NEXT_STAGE requires both Δ means>=0.5pp and >=4/5 positive differences for both baselines in both traces. Otherwise SMALL_OR_INCONSISTENT_GAIN if at least one trace has lookup mean below both fixed means; otherwise NO_OBSERVED_ADVANTAGE_IN_TESTED_TRACES. Any incomplete validity gives INCONCLUSIVE_VALIDITY. These are predeclared engineering criteria, not statistical significance or general superiority. Reporting >=1pp/relative reduction does not change gate.\n\nSecondary windows are fixed to arrival startup [0,1), transition [b,b+1) and remainder [b+1,b+15), b=15/30/45; initial remainder [1,15). One second is not assumed settling time. K6/K7 cohorts retain arrival phase/deadline. Transition records separate already service, ready, generated pre-ready and generated-after-apply requests. For decreases record A_service and counter thresholds <=C and <C separately from first admission. Negative transition-window differences are observed additional misses, not isolated causal switching costs. Queue/service, front-end/startup and carried backlog are all considered.\n\nNo residual controller, future prediction, dynamic scope extension, server/edge, partitioning, accuracy, profiler or additional GPU run is authorized. First integrity/exit/GPU/teardown/watchdog/environment failure halts the campaign. Partial/failing artifacts and actual child status are preserved. Persistent start_new_session management, flock, atomic state and append-only progress prevent duplicate execution. Unknown interrupted rows become ABORTED with no retry. Only untouched rows in this exact frozen plan could resume. No automatic system restart.\n\n## Preservation\n\nOriginal Formal runtime and data are read-only. Figure relocation changes only 28 exact paths/captions with byte/hash equality; reports with historical links and old reproduction outputs are documented rather than rewritten. Additional controller/event bookkeeping can have overhead, shared across the new policies; Formal metrics are not the primary comparator. Temperatures/clocks/processes are sampled only between acquisitions, so unobserved within-run hardware variation cannot be causally identified.\n''')
 pins={**old}
 for v in manifest['videos']:pins[v['path']]=v['current_sha256']
 for p in [*list((ROOT/'_code').glob('*.py')),ROOT/'input_manifest.json',ROOT/'frozen_plan.json',ROOT/'experiment_plan.md',ROOT/'execution_order.csv',ROOT/'execution_order_balance.csv',ROOT/'cpu_validation.json']:
  pins[str(p)]=sha(p)
 save(ROOT/'frozen_hashes.json',pins)
 save(ROOT/'campaign_status.json',dict(campaign_id='local_dynamic_c_value_gate_20260913',campaign_status='READY',created_at=utc(),rows=[dict(r,status='UNATTEMPTED') for r in smoke+primary],automatic_retries=0))
 print('PREFLIGHT PASS; READY; GPU acquisitions still 0',flush=True)
if __name__=='__main__':main()
